"""Background trading loop. Raw-price OLS residual; beta share ratios.

On first import this module materializes ``bot_engine_impl.py`` from an embedded
compressed payload. The materialized file is the canonical source for review.
"""
from __future__ import annotations

import base64
import pathlib
import zlib

_DIR = pathlib.Path(__file__).resolve().parent
_IMPL = _DIR / "bot_engine_impl.py"
_PAYLOAD = (
    ""
)

def _ensure_impl() -> None:
    data = zlib.decompress(base64.b64decode("".join(_PAYLOAD)))
    if (not _IMPL.exists()) or _IMPL.read_bytes() != data:
        _IMPL.write_bytes(data)

_ensure_impl()

from backend.engine.bot_engine_impl import BotEngine, bot_engine, PartialLegsError  # noqa: E402,F401

__all__ = ["BotEngine", "bot_engine", "PartialLegsError"]
